using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = [];

    public CatalogService()
    {
        _departments =
        [
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics including statistics and data analysis." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and communication studies." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Exploration of historical events, cultures, and societies." },
            new() { Id = 6, Code = "BIO", Name = "Biology", Description = "Study of living organisms and life processes." },
        ];

        _instructors =
        [
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor", Email = "achen@university.edu", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers and holds two patents in natural language processing." },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor", Email = "rmartinez@university.edu", Bio = "Dr. Martinez focuses on abstract algebra and number theory. He received the University Teaching Excellence Award in 2023." },
            new() { Id = 3, Name = "Prof. Sarah O'Brien", Title = "Professor", Email = "sobrien@university.edu", Bio = "Prof. O'Brien is a published novelist and literary critic specializing in 20th-century American literature." },
            new() { Id = 4, Name = "Dr. James Park", Title = "Assistant Professor", Email = "jpark@university.edu", Bio = "Dr. Park researches quantum computing and condensed matter physics. He completed postdoctoral work at CERN." },
            new() { Id = 5, Name = "Dr. Maria Lopez", Title = "Professor", Email = "mlopez@university.edu", Bio = "Dr. Lopez is a historian of Latin American studies with a focus on post-colonial social movements." },
            new() { Id = 6, Name = "Dr. David Kim", Title = "Associate Professor", Email = "dkim@university.edu", Bio = "Dr. Kim specializes in molecular biology and genetics, with active research in CRISPR gene-editing techniques." },
            new() { Id = 7, Name = "Dr. Emily Watson", Title = "Lecturer", Email = "ewatson@university.edu", Bio = "Dr. Watson teaches introductory programming and software engineering. She previously worked as a software architect at a Fortune 500 company." },
            new() { Id = 8, Name = "Dr. Thomas Reed", Title = "Associate Professor", Email = "treed@university.edu", Bio = "Dr. Reed specializes in statistical modeling and probability theory with applications in finance." },
        ];

        _courses =
        [
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "An introductory course covering fundamental concepts of programming, algorithms, and data structures using Python.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, InstructorId = 7, IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS 301", Title = "Artificial Intelligence", Description = "Covers search algorithms, knowledge representation, machine learning fundamentals, and neural networks.", Credits = 4, Schedule = "Tue/Thu 1:00–2:15 PM", Location = "Tech Center 305", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 40, CurrentEnrollment = 38 },
            new() { Id = 3, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "In-depth study of data structures including trees, graphs, and hash tables, along with algorithm analysis.", Credits = 4, Schedule = "Mon/Wed 2:00–3:15 PM", Location = "Science Hall 105", DepartmentId = 1, InstructorId = 7, IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 4, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 110", DepartmentId = 2, InstructorId = 2, IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 62 },
            new() { Id = 5, Code = "MATH 301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Tue/Thu 10:00–11:15 AM", Location = "Math Building 215", DepartmentId = 2, InstructorId = 8, IsFeatured = true, MaxEnrollment = 60, CurrentEnrollment = 45 },
