@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Courses — University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <input type="text" name="search" value="@Search" class="form-control" placeholder="Search by title, code, or keyword…" />
    </div>
    <div class="col-md-4">
        <select name="dept" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in Catalog.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@{
    var results = Catalog.SearchCourses(Search, DepartmentId);
}

<p class="text-muted">Showing @results.Count course(s)</p>

@if (results.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria. Try broadening your search.</div>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in results)
            {
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Title</td>
                    <td>@Catalog.GetDepartmentName(course.DepartmentId)</td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                    <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery(Name = "search")]
    public string? Search { get; set; }

    [SupplyParameterFromQuery(Name = "dept")]
    public int? DepartmentId { get; set; }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>@(course?.Title ?? "Course Not Found") — University Course Catalog</PageTitle>

@if (course is null)
{
    <h1>Course Not Found</h1>
    <p>The requested course does not exist. <a href="courses">Back to catalog</a></p>
}
else
{
    var instructor = Catalog.GetInstructor(course.InstructorId);
    var department = Catalog.GetDepartment(course.DepartmentId);
    var spotsRemaining = course.MaxEnrollment - course.CurrentEnrollment;

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            @if (department is not null)
            {
                <li class="breadcrumb-item"><a href="departments/@department.Id">@department.Name</a></li>
            }
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <h1>@course.Code — @course.Title</h1>

    <div class="row mt-4">
        <div class="col-md-8">
            <h4>Description</h4>
            <p>@course.Description</p>

            <h4>Schedule &amp; Location</h4>
            <dl class="row">
                <dt class="col-sm-3">Schedule</dt>
                <dd class="col-sm-9">@course.Schedule</dd>
                <dt class="col-sm-3">Location</dt>
                <dd class="col-sm-9">@course.Location</dd>
                <dt class="col-sm-3">Credits</dt>
                <dd class="col-sm-9">@course.Credits</dd>
            </dl>

            <h4>Enrollment</h4>
            <p>
                @course.CurrentEnrollment / @course.MaxEnrollment enrolled
                @if (spotsRemaining > 0)
                {
                    <span class="badge bg-success ms-2">@spotsRemaining spots remaining</span>
                }
                else
                {
                    <span class="badge bg-danger ms-2">Full</span>
                }
            </p>

            <a href="enroll?courseId=@course.Id" class="btn btn-primary">Request Enrollment</a>
        </div>

        <div class="col-md-4">
            @if (instructor is not null)
            {
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">Instructor</h5>
                        <h6>@instructor.Name</h6>
                        <p class="text-muted mb-1">@instructor.Title</p>
                        <p class="mb-2"><a href="mailto:@instructor.Email">@instructor.Email</a></p>
                        <p class="small">@instructor.Bio</p>
                    </div>
                </div>
            }
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
    }
}

