@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to request enrollment in a course. You will receive confirmation via your university email.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@model.StudentName</strong>. Your enrollment request for
            <strong>@(Catalog.GetCourse(model.CourseId)?.Title ?? "the selected course")</strong>
            has been received.</p>
        <p class="mb-0">A confirmation will be sent to <strong>@model.Email</strong>.</p>
    </div>
    <a href="enroll" class="btn btn-outline-primary">Submit Another Request</a>
}
else
{
    <EditForm method="post" Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <InputText id="studentName" @bind-Value="model.StudentName" class="form-control" />
            <ValidationMessage For="() => model.StudentName" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" @bind-Value="model.StudentId" class="form-control" placeholder="e.g. STU123456" />
            <ValidationMessage For="() => model.StudentId" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="email" class="form-label">University Email</label>
            <InputText id="email" @bind-Value="model.Email" class="form-control" placeholder="you@university.edu" />
            <ValidationMessage For="() => model.Email" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" @bind-Value="model.CourseId" class="form-select">
                <option value="0">— Select a course —</option>
                @foreach (var course in Catalog.GetCourses())
                {
                    <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                }
            </InputSelect>
            <ValidationMessage For="() => model.CourseId" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "courseId")]
    public int? PreselectedCourseId { get; set; }

    private bool submitted;

    protected override void OnInitialized()
    {
        if (PreselectedCourseId.HasValue && model.CourseId == 0)
        {
            model.CourseId = PreselectedCourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        Catalog.SubmitEnrollmentRequest(model);
        submitted = true;
    }
}

